a:1:{s:65:"../../../packages/steam-sdk/src/Support/RateLimitedHttpClient.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:38:"SteamSdk\Support\RateLimitedHttpClient";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:574:"/**
 * Small keyless HTTP client for public Steam endpoints.
 *
 * - calls $beforeRequest (if given) before every network attempt (throttling hook);
 * - keeps at least $minIntervalSeconds between two consecutive attempts (start to start);
 * - retries HTTP 429 / 5xx and transport errors with a 1s / 2s backoff;
 * - throws SteamRequestException when the last attempt fails.
 *
 * The class is intentionally non-final: tests subclass it and override
